import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// cp.async based asynchronous copy helpers (Ampere+) with a synchronous
// fallback for older architectures, used to implement true hardware-level
// pipelined global->shared copies instead of relying solely on software
// double buffering with blocking loads through registers.
__device__ __forceinline__ void cp_async_cg_16B(void* smem_ptr, const void* gmem_ptr) {
#if __CUDA_ARCH__ >= 800
  unsigned int smem_int = static_cast<unsigned int>(__cvta_generic_to_shared(smem_ptr));
  asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n"
               :: "r"(smem_int), "l"(gmem_ptr));
#else
  *reinterpret_cast<float4*>(smem_ptr) = *reinterpret_cast<const float4*>(gmem_ptr);
#endif
}
__device__ __forceinline__ void cp_async_commit_group() {
#if __CUDA_ARCH__ >= 800
  asm volatile("cp.async.commit_group;\n");
#endif
}
template <int N>
__device__ __forceinline__ void cp_async_wait_group() {
#if __CUDA_ARCH__ >= 800
  asm volatile("cp.async.wait_group %0;\n" :: "n"(N));
#endif
}
// Tiled shared-memory GEMM: C = A @ B
// A: (M,K) row-major, B: (K,N) row-major, C: (M,N) row-major
template <int BM, int BN, int BK, int TM, int TN>
__global__ void gemm_kernel(const float* __restrict__ A,
                             const float* __restrict__ B,
                             float* __restrict__ C,
                             int M, int N, int K) {
  // Double-buffered (software pipelined) shared memory staging: while the
  // current K-tile is being consumed by the compute loop, the next K-tile's
  // global loads are already in flight, hiding global memory latency behind
  // arithmetic instead of stalling at a barrier after every load.
  extern __shared__ float smem[];
  float* sA_raw[2];
  float* sB_raw[2];
  sA_raw[0] = smem;
  sA_raw[1] = smem + BM * BK;
  sB_raw[0] = smem + 2 * BM * BK;
  sB_raw[1] = smem + 2 * BM * BK + BK * BN;
  // Global tensors described with CuTe layouts
  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(M, K), make_stride(K, 1));
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(K, N), make_stride(N, 1));
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(M, N), make_stride(N, 1));
  int by = blockIdx.y; // tile index along M
  int bx = blockIdx.x; // tile index along N
  // Tile the global tensors for this CTA. The '_' wildcard keeps the
  // reduction dimension (K) as an extra iterable mode.
  Tensor gA = local_tile(mA, make_shape(Int<BM>{}, Int<BK>{}), make_coord(by, _));   // (BM,BK,kTiles)
  Tensor gB = local_tile(mB, make_shape(Int<BK>{}, Int<BN>{}), make_coord(_, bx));   // (BK,BN,kTiles)
  Tensor gC = local_tile(mC, make_shape(Int<BM>{}, Int<BN>{}), make_coord(by, bx));  // (BM,BN)
  const int tid_x = threadIdx.x; // 0..(BN/TN - 1)
  const int tid_y = threadIdx.y; // 0..(BM/TM - 1)
  const int tid = tid_y * blockDim.x + tid_x;
  const int nThreads = blockDim.x * blockDim.y;
  float acc[TM][TN];
  #pragma unroll
  for (int i = 0; i < TM; ++i)
    #pragma unroll
    for (int j = 0; j < TN; ++j)
      acc[i][j] = 0.0f;
  const int kTiles = size<2>(gA);
  const int totalVecA = (BM * BK) / 4;
  const int totalVecB = (BK * BN) / 4;
  // Cooperative vectorized load of the A/B tile for K-index `kt` into
  // shared-memory buffer `buf`.
  auto load_tile = [&] (int buf, int kt) {
    for (int vec_idx = tid; vec_idx < totalVecA; vec_idx += nThreads) {
      int r = vec_idx / (BK / 4);
      int c4 = vec_idx % (BK / 4);
      int a_row = by * BM + r;
      int a_col = kt * BK + c4 * 4;
      const float4* a_ptr = reinterpret_cast<const float4*>(A + (size_t)a_row * K + a_col);
      float4* sA_ptr = reinterpret_cast<float4*>(sA_raw[buf] + r * BK + c4 * 4);
      cp_async_cg_16B(sA_ptr, a_ptr);
    }
    for (int vec_idx = tid; vec_idx < totalVecB; vec_idx += nThreads) {
      int r = vec_idx / (BN / 4);
      int c4 = vec_idx % (BN / 4);
      int b_row = kt * BK + r;
      int b_col = bx * BN + c4 * 4;
      const float4* b_ptr = reinterpret_cast<const float4*>(B + (size_t)b_row * N + b_col);
      float4* sB_ptr = reinterpret_cast<float4*>(sB_raw[buf] + r * BN + c4 * 4);
      cp_async_cg_16B(sB_ptr, b_ptr);
    }
  };
  // Consume shared-memory buffer `buf` for the whole BK reduction step,
  // accumulating into the per-thread register tile.
  auto compute_tile = [&] (int buf) {
    Tensor sA = make_tensor(make_smem_ptr(sA_raw[buf]),
                            make_shape(Int<BM>{}, Int<BK>{}),
                            make_stride(Int<BK>{}, Int<1>{}));
    float* sB_ptr_base = sB_raw[buf];
    for (int k = 0; k < BK; ++k) {
      float a_frag[TM];
      float b_frag[TN];
      #pragma unroll
      for (int i = 0; i < TM; ++i) a_frag[i] = sA(tid_y * TM + i, k);
      #pragma unroll
      for (int j = 0; j < TN; j += 4) {
        const float4* b_ptr0 = reinterpret_cast<const float4*>(&sB_ptr_base[k * BN + tid_x * TN + j]);
        float4 b_val0 = b_ptr0[0];
        b_frag[j + 0] = b_val0.x; b_frag[j + 1] = b_val0.y; b_frag[j + 2] = b_val0.z; b_frag[j + 3] = b_val0.w;
      }
      #pragma unroll
      for (int i = 0; i < TM; ++i) {
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
          acc[i][j] += a_frag[i] * b_frag[j];
        }
      }
    }
  };
  // Prologue: issue the first K-tile's asynchronous copies and wait for
  // them to land in shared memory before entering the pipelined loop.
  load_tile(0, 0);
  cp_async_commit_group();
  cp_async_wait_group<0>();
  __syncthreads();
  for (int kt = 0; kt < kTiles; ++kt) {
    int cur = kt & 1;
    int nxt = 1 - cur;
    if (kt + 1 < kTiles) {
      // Issue the next tile's async copies; the hardware copy engine
      // overlaps them with this tile's compute instead of stalling threads.
      load_tile(nxt, kt + 1);
      cp_async_commit_group();
      // Ensure at most the just-issued group remains outstanding, i.e. the
      // previously issued group (feeding buffer `cur`) has completed.
      cp_async_wait_group<1>();
    } else {
      // No more tiles to prefetch; make sure the current buffer's copies
      // (issued last iteration) have fully completed.
      cp_async_wait_group<0>();
    }
    __syncthreads();
    compute_tile(cur);
    __syncthreads();
  }
  #pragma unroll
  for (int i = 0; i < TM; ++i) {
    int row = by * BM + tid_y * TM + i;
    #pragma unroll
    for (int j = 0; j < TN; j += 4) {
      float4* c_ptr0 = reinterpret_cast<float4*>(&C[(size_t)row * N + bx * BN + tid_x * TN + j]);
      float4 out0 = make_float4(acc[i][j + 0], acc[i][j + 1], acc[i][j + 2], acc[i][j + 3]);
      c_ptr0[0] = out0;
    }
  }
}
torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");
  int M = (int)A.size(0);
  int K = (int)A.size(1);
  int K2 = (int)B.size(0);
  int N = (int)B.size(1);
  TORCH_CHECK(K == K2, "Inner dimensions of A and B must match");
  constexpr int BM = 128;
  constexpr int BN = 128;
  constexpr int BK = 32;
  constexpr int TM = 4;
  constexpr int TN = 4;
  TORCH_CHECK(M % BM == 0, "M must be divisible by ", BM);
  TORCH_CHECK(N % BN == 0, "N must be divisible by ", BN);
  TORCH_CHECK(K % BK == 0, "K must be divisible by ", BK);
  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C = torch::empty({M, N}, A.options());
  dim3 block(BN / TN, BM / TM); // (32,32) -> 1024 threads/block; smaller per-thread register tile (TM=4,TN=4) cuts register usage (was 88 regs/thread, occupancy-limited to ~33%), raising occupancy per profiler guidance
  dim3 grid(N / BN, M / BM);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  // Double-buffered shared memory staging needs room for two A/B tiles
  // simultaneously; request it as dynamic shared memory and opt in to a
  // larger-than-default per-block shared memory carve-out.
  size_t smem_bytes = 2 * (size_t)(BM * BK + BK * BN) * sizeof(float);
  static bool attr_set = false;
  if (!attr_set) {
    cudaFuncSetAttribute(gemm_kernel<BM, BN, BK, TM, TN>,
                         cudaFuncAttributeMaxDynamicSharedMemorySize,
                         (int)smem_bytes);
    attr_set = true;
  }
  gemm_kernel<BM, BN, BK, TM, TN><<<grid, block, smem_bytes, stream>>>(
      A_c.data_ptr<float>(),
      B_c.data_ptr<float>(),
      C.data_ptr<float>(),
      M, N, K);
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "gemm_kernel launch failed: ", cudaGetErrorString(err));
  return C;
}
"""

cute_gemm_ext = load_inline(
    name="cute_gemm_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a single square matrix multiplication (C = A * B)
    using a custom CuTe-based tiled shared-memory GEMM kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_gemm_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matmul(A.contiguous(), B.contiguous())

